#' Factorial Design
#'
#' 
#' @param data .
#' @param outcome .
#' @param factorA .
#' @param controlA .
#' @param factorB .
#' @param controlB .
#' @param covs .
#' @param block .
#' @param cluster .
#' @param se .
#' @param level .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cells} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$main} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$simple} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$inter} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ign} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cells$asDF}
#'
#' \code{as.data.frame(results$cells)}
#'
#' @export
exfact <- function(
    data,
    outcome,
    factorA,
    controlA = "",
    factorB,
    controlB = "",
    covs,
    block,
    cluster,
    se = "auto",
    level = 95,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("exfact requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(factorA)) factorA <- jmvcore::resolveQuo(jmvcore::enquo(factorA))
    if ( ! missing(factorB)) factorB <- jmvcore::resolveQuo(jmvcore::enquo(factorB))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(block)) block <- jmvcore::resolveQuo(jmvcore::enquo(block))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(factorA), factorA, NULL),
            `if`( ! missing(factorB), factorB, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(block), block, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- exfactOptions$new(
        outcome = outcome,
        factorA = factorA,
        controlA = controlA,
        factorB = factorB,
        controlB = controlB,
        covs = covs,
        block = block,
        cluster = cluster,
        se = se,
        level = level,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- exfactClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

